import os, json, sys
sys.path.append('storage/shared/agents/kairos/VEN/util')
import plot_boundary

TARGETS = [
    ("storage/shared/atlas/edges/zephyr/variance/hinge_metrics.csv",
     "storage/shared/atlas/edges/zephyr/variance/boundary_panel.png"),
    ("storage/shared/atlas/edges/nova/ven_entropy/hinge_metrics.csv",
     "storage/shared/atlas/edges/nova/ven_entropy/boundary_panel.png"),
]

def build(csv_path, png_path):
    if not os.path.exists(csv_path):
        return {'csv': csv_path, 'png': png_path, 'ok': False, 'reason': 'csv_missing'}
    res = plot_boundary.plot(csv_path, png_path)
    return {'csv': csv_path, 'png': png_path, 'ok': res.get('ok', False), 'reason': res.get('reason')}

def main():
    results = [build(csvp, pngp) for csvp, pngp in TARGETS]
    print(json.dumps({'built': results}, indent=2))

if __name__ == "__main__":
    main()
